   304	    private static async Task<string> ReadSuccessfulBodyAsync(
   305	        string command,
   306	        HttpResponseMessage response,
   307	        CancellationToken cancellationToken)
   308	    {
   309	        var body = await ReadBodyWithLimitAsync(response.Content, MaxResponseBodyBytes, cancellationToken);
   310	        if (!response.IsSuccessStatusCode)
   311	        {
   312	            throw new JobTrackApiException(
   313	                command,
   314	                response.StatusCode,
   315	                response.ReasonPhrase,
   316	                body.Text,
   317	                body.Truncated,
   318	                MaxResponseBodyBytes);
   319	        }
   320	
   321	        if (body.Truncated)
   322	        {
   323	            throw new InvalidOperationException($"{command}: response body exceeded {MaxResponseBodyBytes} bytes.");
   324	        }
   325	
   326	        return body.Text;
   327	    }
