   368	    private static string DecodeBody(HttpContent content, byte[] body)
   369	    {
   370	        var charset = content.Headers.ContentType?.CharSet?.Trim('"');
   371	        if (!string.IsNullOrWhiteSpace(charset))
   372	        {
   373	            try
   374	            {
   375	                return Encoding.GetEncoding(charset).GetString(body);
   376	            }
   377	            catch (ArgumentException)
   378	            {
   379	                // Fall back to UTF-8 for malformed server charset metadata.
   380	            }
   381	        }
   382	
   383	        return Encoding.UTF8.GetString(body);
   384	    }
