   824	                if (nestedAuthor is not null)
   825	                {
   826	                    return BoundedScalar(nestedAuthor, index, "author", MaxAuthorLength);
   827	                }
   828	            }
   829	        }
   830	
   831	        var fallbackAuthor = FirstScalar(comment, FallbackAuthorPropertyNames);
   832	        if (fallbackAuthor is not null)
   833	        {
   834	            return BoundedScalar(fallbackAuthor, index, "author", MaxAuthorLength);
   835	        }
